package com.manishrawat.realestate.servlet; import com.manishrawat.realestate.model.User; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*; @WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{User u=(User)r.getSession().getAttribute("user");r.setAttribute("user",u);r.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(r,s);}}
